from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = '/root/data/workbook.xlsx'
wb = load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)

task = wb['Task']
data = wb['Data']

print('\nTask sheet dimensions:', task.max_row, task.max_column)
print('Data sheet dimensions:', data.max_row, data.max_column)

print('\nTask labels/codes for lookup blocks:')
for start, end in [(12,17),(19,24),(26,31)]:
    print(f'Rows {start}:{end}')
    for r in range(start, end+1):
        vals = {get_column_letter(c): task.cell(r,c).value for c in range(1, 6)}
        print(f'  row {r}: {vals}')

print('\nTask series codes D12:D17, D19:D24, D26:D31:')
for start, end in [(12,17),(19,24),(26,31)]:
    for r in range(start, end+1):
        print(f'D{r} = {task.cell(r,4).value!r}')

print('\nTask row 10 columns H-L (years):')
for c in range(8,13):
    print(f'{get_column_letter(c)}10 = {task.cell(10,c).value!r}')

print('\nTask H35:L40 labels/current content (with B-D labels):')
for r in range(35,41):
    labels = {get_column_letter(c): task.cell(r,c).value for c in range(1, 5)}
    targets = {get_column_letter(c)+str(r): task.cell(r,c).value for c in range(8,13)}
    print(f'row {r}: labels={labels}, targets={targets}')

print('\nTask H42:H47 labels/current content (with B-D labels and H-L current):')
for r in range(42,48):
    labels = {get_column_letter(c): task.cell(r,c).value for c in range(1, 5)}
    targets = {get_column_letter(c)+str(r): task.cell(r,c).value for c in range(8,13)}
    print(f'row {r}: labels={labels}, targets={targets}')

print('\nTask H50 label/current content (with B-D labels and H-L current):')
r=50
labels = {get_column_letter(c): task.cell(r,c).value for c in range(1, 5)}
targets = {get_column_letter(c)+str(r): task.cell(r,c).value for c in range(8,13)}
print(f'row {r}: labels={labels}, targets={targets}')

print('\nAny existing content in all yellow target ranges:')
for start, end in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(start, end+1):
        contents = []
        for c in range(8,13):
            v = task.cell(r,c).value
            if v is not None:
                contents.append(f'{get_column_letter(c)}{r}={v!r}')
        if contents:
            print('  ' + ', '.join(contents))

print('\nData sheet row 21 headers (all used columns):')
headers = []
for c in range(1, data.max_column+1):
    v = data.cell(21,c).value
    if v is not None:
        headers.append(f'{get_column_letter(c)}21={v!r}')
print('  ' + ', '.join(headers))

print('\nData sheet sample rows 21-38 (all used columns A through max):')
for r in range(21,39):
    row = {get_column_letter(c): data.cell(r,c).value for c in range(1, data.max_column+1)}
    print(f'row {r}: {row}')

print('\nNon-empty Data cells around rows 1-45:')
for r in range(1, min(data.max_row,45)+1):
    entries=[]
    for c in range(1, data.max_column+1):
        v=data.cell(r,c).value
        if v is not None:
            entries.append(f'{get_column_letter(c)}={v!r}')
    if entries:
        print(f'row {r}: ' + ', '.join(entries))

