from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = '/root/output/result.xlsx'
wb = load_workbook(path, data_only=False)
print('Reloaded:', path)
print('Sheet names:', wb.sheetnames)
ws = wb['Task']
errors = []

ranges = [(12,17), (19,24), (26,31), (35,40), (42,47), (50,50)]
print('\nTarget cell formulas:')
for start, end in ranges:
    print(f'Rows {start}:{end}')
    for r in range(start, end + 1):
        row_values = []
        for c in range(8, 13):
            addr = f'{get_column_letter(c)}{r}'
            value = ws.cell(r, c).value
            row_values.append(f'{addr}={value!r}')
            if value is None or value == '':
                errors.append(f'{addr} is empty')
            elif not (isinstance(value, str) and value.startswith('=')):
                errors.append(f'{addr} is not a formula string: {value!r}')
        print('  ' + '; '.join(row_values))

# Precise reference checks for lookup formulas.
for start, end in [(12,17), (19,24), (26,31)]:
    for r in range(start, end+1):
        for c in range(8,13):
            col = get_column_letter(c)
            v = ws.cell(r,c).value
            required = ['Data!$H$21:$L$38', 'Data!$D$21:$D$38', 'Data!$H$4:$L$4', f'MATCH($D{r},', f'MATCH({col}$10,']
            for token in required:
                if token not in v:
                    errors.append(f'{col}{r} missing expected token {token}: {v}')

# Verify no extra sheets.
if wb.sheetnames != ['Task', 'Data']:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')

print('\nVerification summary:')
if errors:
    print('FAILED')
    for e in errors:
        print('ERROR:', e)
    raise SystemExit(1)
else:
    print('PASSED: all target cells are non-empty formula strings starting with =')
    print('PASSED: lookup formulas reference Data!$H$21:$L$38 values, Data!$D$21:$D$38 series codes, and Data!$H$4:$L$4 year headers')
    print('PASSED: sheet names unchanged')
